using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using PokeMarketApi.Data;using PokeMarketApi.Models;namespace PokeMarketApi.Controllers;[Authorize]public class SellController(MarketContext db,UserManager<IdentityUser> users):Controller{public async Task<IActionResult> Index()=>View(await db.SellerListings.OrderByDescending(x=>x.CreatedAt).ToListAsync());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Create(string productName,string productType,string? imageUrl,string grade,decimal priceQar){db.SellerListings.Add(new SellerListing{SellerId=users.GetUserId(User)!,ProductName=productName,ProductType=productType,ImageUrl=imageUrl,Grade=grade,PriceQar=priceQar});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}}